message.content:
{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2156-11-25 20:30:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I’ll be your doctor during this stay. Can you tell me what brought you in today?"
    },
    {
      "turn_number": 2,
      "time": "2156-11-25 20:31:00",
      "speaker": "Patient",
      "text": "Hi. I’ve been having this sharp pain on my right side, especially when I walk. It comes with palpitations. And my usual stomach pain, nausea, and vomiting are still here."
    },
    {
      "turn_number": 3,
      "time": "2156-11-25 20:32:00",
      "speaker": "Doctor",
      "text": "Okay. Any chest pain or shortness of breath?"
    },
    {
      "turn_number": 4,
      "time": "2156-11-25 20:33:00",
      "speaker": "Patient",
      "text": "Yes, the chest pain is on the right side, sharp, worse with walking. I’ve been feeling my heart racing a lot."
    },
    {
      "turn_number": 5,
      "time": "2156-11-25 20:34:00",
      "speaker": "Doctor",
      "text": "Got it. And how about your diabetes? Are you managing your insulin?"
    },
    {
      "turn_number": 6,
      "time": "2156-11-25 20:35:00",
      "speaker": "Patient",
      "text": "I haven’t taken my short-acting insulin since Wednesday. I lost my glucometer, so I can’t check my sugars."
    },
    {
      "turn_number": 7,
      "time": "2156-11-25 20:36:00",
      "speaker": "Doctor",
      "text": "That could explain why your blood sugar was high when you arrived—499. We’ll help you manage that here."
    },
    {
      "turn_number": 8,
      "time": "2156-11-25 20:37:00",
      "speaker": "Patient",
      "text": "Okay. My PCP started me on levofloxacin for my GJ tube site—thought it might be infected."
    },
    {
      "turn_number": 9,
      "time": "2156-11-25 20:38:00",
      "speaker": "Doctor",
      "text": "Noted. We’ll continue that for now. We’re going to run some tests to check your chest pain and make sure your pancreas isn’t flaring up again."
    },
    {
      "turn_number": 10,
      "time": "2156-11-25 20:39:00",
      "speaker": "Patient",
      "text": "I’ve had so many admissions for this. I just want the pain under control."
    },
    {
      "turn_number": 11,
      "time": "2156-11-25 20:40:00",
      "speaker": "Doctor",
      "text": "We’ll work on that. You’re getting Dilaudid for pain and insulin to bring your sugar down. We’ll monitor you closely."
    },
    {
      "turn_number": 12,
      "time": "2156-11-26 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. Your EKG and first troponin were normal. We’ll repeat those to rule out a heart issue."
    },
    {
      "turn_number": 13,
      "time": "2156-11-26 08:16:00",
      "speaker": "Patient",
      "text": "So it’s not my heart?"
    },
    {
      "turn_number": 14,
      "time": "2156-11-26 08:17:00",
      "speaker": "Doctor",
      "text": "No sign of a heart attack. Your tachycardia is likely from pain or anxiety. You’re wearing a Holter monitor—cardiology will review that."
    },
    {
      "turn_number": 15,
      "time": "2156-11-26 08:18:00",
      "speaker": "Patient",
      "text": "That’s a relief. What about my GJ tube? It’s been leaking a bit."
    },
    {
      "turn_number": 16,
      "time": "2156-11-26 08:19:00",
      "speaker": "Doctor",
      "text": "We’ll keep an eye on it. If it comes out, we may need to replace it. For now, it looks okay."
    },
    {
      "turn_number": 17,
      "time": "2156-11-27 09:00:00",
      "speaker": "Doctor",
      "text": "We have a problem. You pulled your GJ tube out overnight."
    },
    {
      "turn_number": 18,
      "time": "2156-11-27 09:01:00",
      "speaker": "Patient",
      "text": "I didn’t mean to. It was uncomfortable."
    },
    {
      "turn_number": 19,
      "time": "2156-11-27 09:02:00",
      "speaker": "Doctor",
      "text": "We’ve placed a Foley catheter temporarily. Interventional Radiology will replace the GJ tube tomorrow."
    },
    {
      "turn_number": 20,
      "time": "2156-11-27 09:03:00",
      "speaker": "Patient",
      "text": "Will it hurt?"
    },
    {
      "turn_number": 21,
      "time": "2156-11-27 09:04:00",
      "speaker": "Doctor",
      "text": "You’ll be sedated. It’s a quick procedure under X-ray guidance. You’ll be fine."
    },
    {
      "turn_number": 22,
      "time": "2156-11-28 10:00:00",
      "speaker": "Doctor",
      "text": "The GJ tube was successfully replaced this morning. You can start taking oral meds again."
    },
    {
      "turn_number": 23,
      "time": "2156-11-28 10:01:00",
      "speaker": "Patient",
      "text": "Thank you. I feel better already."
    },
    {
      "turn_number": 24,
      "time": "2156-11-29 14:00:00",
      "speaker": "Doctor",
      "text": "You’ve developed a low-grade fever and some tenderness near the tube site."
    },
    {
      "turn_number": 25,
      "time": "2156-11-29 14:01:00",
      "speaker": "Patient",
      "text": "Is it infected?"
    },
    {
      "turn_number": 26,
      "time": "2156-11-29 14:02:00",
      "speaker": "Doctor",
      "text": "We did a CT scan. No free air or abscess. But there’s redness, so we’re starting clindamycin just in case."
    },
    {
      "turn_number": 27,
      "time": "2156-11-29 14:03:00",
      "speaker": "Patient",
      "text": "Is that safe with my penicillin allergy?"
    },
    {
      "turn_number": 28,
      "time": "2156-11-29 14:04:00",
      "speaker": "Doctor",
      "text": "Yes, clindamycin is safe. It’s not related to penicillin."
    },
    {
      "turn_number": 29,
      "time": "2156-11-30 08:30:00",
      "speaker": "Doctor",
      "text": "Your fever is gone, and the white count is improving. The antibiotic is working."
    },
    {
      "turn_number": 30,
      "time": "2156-11-30 08:31:00",
      "speaker": "Patient",
      "text": "Good. My pain is better too. Can I eat?"
    },
    {
      "turn_number": 31,
      "time": "2156-11-30 08:32:00",
      "speaker": "Doctor",
      "text": "Yes, we’re advancing you to a regular diet. You’re not using the tube for feeds, so oral intake is key."
    },
    {
      "turn_number": 32,
      "time": "2156-12-01 09:00:00",
      "speaker": "Doctor",
      "text": "Your repeat CT shows the GJ tube is in place, no complications. Pancreas looks stable—no acute flare."
    },
    {
      "turn_number": 33,
      "time": "2156-12-01 09:01:00",
      "speaker": "Patient",
      "text": "So it’s still chronic pancreatitis?"
    },
    {
      "turn_number": 34,
      "time": "2156-12-01 09:02:00",
      "speaker": "Doctor",
      "text": "Yes, with calcifications, but no acute signs. Your pain is managed with Dilaudid, and we’re limiting extra doses to one per day to stay safe."
    },
    {
      "turn_number": 35,
      "time": "2156-12-01 09:03:00",
      "speaker": "Patient",
      "text": "I just want to feel in control."
    },
    {
      "turn_number": 36,
      "time": "2156-12-01 09:04:00",
      "speaker": "Doctor",
      "text": "We’re letting you choose when to take that extra dose—like before procedures or when pain spikes. That way, you have some say."
    },
    {
      "turn_number": 37,
      "time": "2156-12-02 10:15:00",
      "speaker": "Doctor",
      "text": "Your blood sugar is still high—around 265. We’re worried about adjusting insulin because your eating is unpredictable."
    },
    {
      "turn_number": 38,
      "time": "2156-12-02 10:16:00",
      "speaker": "Patient",
      "text": "I’ll try to eat more regularly."
    },
    {
      "turn_number": 39,
      "time": "2156-12-02 10:17:00",
      "speaker": "Doctor",
      "text": "We consulted endocrinology. You’ll go home on 60 units of Lantus at bedtime and a new sliding scale for Humalog."
    },
    {
      "turn_number": 40,
      "time": "2156-12-02 10:18:00",
      "speaker": "Patient",
      "text": "I need to get a new glucometer."
    },
    {
      "turn_number": 41,
      "time": "2156-12-02 10:19:00",
      "speaker": "Doctor",
      "text": "Yes, please do. Checking your sugars is essential to avoid highs and lows."
    },
    {
      "turn_number": 42,
      "time": "2156-12-03 08:45:00",
      "speaker": "Doctor",
      "text": "Your hemoglobin dropped a bit—from 14.3 to 11.9. We’re watching it. Could be from chronic disease or mild malnutrition."
    },
    {
      "turn_number": 43,
      "time": "2156-12-03 08:46:00",
      "speaker": "Patient",
      "text": "Should I be worried?"
    },
    {
      "turn_number": 44,
      "time": "2156-12-03 08:47:00",
      "speaker": "Doctor",
      "text": "Not acutely. It’s mild. Eating well and managing your gastroparesis will help."
    },
    {
      "turn_number": 45,
      "time": "2156-12-04 09:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. Pain is controlled, eating regularly, and your labs are improving."
    },
    {
      "turn_number": 46,
      "time": "2156-12-04 09:01:00",
      "speaker": "Patient",
      "text": "Can I go home soon?"
    },
    {
      "turn_number": 47,
      "time": "2156-12-04 09:02:00",
      "speaker": "Doctor",
      "text": "We’re planning for discharge in a couple of days. You’ll finish the 3-day clindamycin course at home."
    },
    {
      "turn_number": 48,
      "time": "2156-12-05 10:20:00",
      "speaker": "Doctor",
      "text": "Your latest labs look good. Hemoglobin is up to 12.9, white count normal, sodium improved from 132 to 136."
    },
    {
      "turn_number": 49,
      "time": "2156-12-05 10:21:00",
      "speaker": "Patient",
      "text": "What about the rash on my arms?"
    },
    {
      "turn_number": 50,
      "time": "2156-12-05 10:22:00",
      "speaker": "Doctor",
      "text": "It’s likely not serious—maybe a reaction to a med or stress. It’s not spreading. Keep an eye on it."
    },
    {
      "turn_number": 51,
      "time": "2156-12-06 08:30:00",
      "speaker": "Doctor",
      "text": "Discharge is tomorrow. You’ll go home with Dilaudid for pain, but only one pill every three hours after the first five days."
    },
    {
      "turn_number": 52,
      "time": "2156-12-06 08:31:00",
      "speaker": "Patient",
      "text": "I need to see my pain doctor for refills."
    },
    {
      "turn_number": 53,
      "time": "2156-12-06 08:32:00",
      "speaker": "Doctor",
      "text": "Yes, follow up with your PCP for that. Also, continue omeprazole, your inhalers, and the new insulin regimen."
    },
    {
      "turn_number": 54,
      "time": "2156-12-06 08:33:00",
      "speaker": "Patient",
      "text": "And the clindamycin?"
    },
    {
      "turn_number": 55,
      "time": "2156-12-06 08:34:00",
      "speaker": "Doctor",
      "text": "Take it twice a day for three days. Stop after that. No refills."
    },
    {
      "turn_number": 56,
      "time": "2156-12-06 08:35:00",
      "speaker": "Patient",
      "text": "I’ll do my best."
    },
    {
      "turn_number": 57,
      "time": "2156-12-07 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re cleared to go home. You’re alert, walking, and your pain is manageable."
    },
    {
      "turn_number": 58,
      "time": "2156-12-07 09:01:00",
      "speaker": "Patient",
      "text": "Thank you. It was rough, but I feel better."
    },
    {
      "turn_number": 59,
      "time": "2156-12-07 09:02:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Remember: take the clindamycin, use your new insulin doses, and follow up with your doctors."
    },
    {
      "turn_number": 60,
      "time": "2156-12-07 09:03:00",
      "speaker": "Patient",
      "text": "I will. And no driving when I take Dilaudid."
    },
    {
      "turn_number": 61,
      "time": "2156-12-07 09:04:00",
      "speaker": "Doctor",
      "text": "Exactly. Stay safe. Call if you have fever, severe pain, or high blood sugars."
    },
    {
      "turn_number": 62,
      "time": "2156-12-07 09:05:00",
      "speaker": "Patient",
      "text": "I’ll keep in touch. Thanks again."
    },
    {
      "turn_number": 63,
      "time": "2156-12-07 09:06:00",
      "speaker": "Doctor",
      "text": "Take care. We’re here if you need us."
    },
    {
      "turn_number": 64,
      "time": "2156-12-07 10:00:00",
      "speaker": "Doctor",
      "text": "Just a final check before discharge. Any last questions?"
    },
    {
      "turn_number": 65,
      "time": "2156-12-07 10:01:00",
      "speaker": "Patient",
      "text": "No, I think I’ve got it all."
    },
    {
      "turn_number": 66,
      "time": "2156-12-07 10:02:00",
      "speaker": "Doctor",
      "text": "Great. You’re doing well. Go home, rest, and follow the plan."
    },
    {
      "turn_number": 67,
      "time": "2156-12-07 11:00:00",
      "speaker": "Doctor",
      "text": "Your discharge papers are ready. Nurse will go over meds and instructions one more time."
    },
    {
      "turn_number": 68,
      "time": "2156-12-07 11:01:00",
      "speaker": "Patient",
      "text": "Okay, thanks."
    },
    {
      "turn_number": 69,
      "time": "2156-12-07 12:00:00",
      "speaker": "Doctor",
      "text": "Just confirming—you understand to take clindamycin for three days, then stop?"
    },
    {
      "turn_number": 70,
      "time": "2156-12-07 12:01:00",
      "speaker": "Patient",
      "text": "Yes, two capsules every six hours for three days."
    },
    {
      "turn_number": 71,
      "time": "2156-12-07 12:02:00",
      "speaker": "Doctor",
      "text": "Perfect. And insulin—60 units Lantus at bedtime, Humalog with meals using the new scale."
    },
    {
      "turn_number": 72,
      "time": "2156-12-07 12:03:00",
      "speaker": "Patient",
      "text": "Got it. I’ll get a new glucometer today."
    },
    {
      "turn_number": 73,
      "time": "2156-12-07 12:04:00",
      "speaker": "Doctor",
      "text": "Good plan. And call if your GJ site gets red or painful again."
    },
    {
      "turn_number": 74,
      "time": "2156-12-07 12:05:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 75,
      "time": "2156-12-07 13:00:00",
      "speaker": "Doctor",
      "text": "You’re officially discharged. Take care of yourself."
    },
    {
      "turn_number": 76,
      "time": "2156-12-07 13:01:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor."
    },
    {
      "turn_number": 77,
      "time": "2156-12-07 13:02:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Stay in touch with your team."
    },
    {
      "turn_number": 78,
      "time": "2156-12-07 13:15:00",
      "speaker": "Doctor",
      "text": "One last thing—your urine was red earlier. Any more of that?"
    },
    {
      "turn_number": 79,
      "time": "2156-12-07 13:16:00",
      "speaker": "Patient",
      "text": "No, not since that one time."
    },
    {
      "turn_number": 80,
      "time": "2156-12-07 13:17:00",
      "speaker": "Doctor",
      "text": "We’ll note it. Could be from meds or dehydration. Stay hydrated and mention it at your follow-up."
    },
    {
      "turn_number": 81,
      "time": "2156-12-07 13:18:00",
      "speaker": "Patient",
      "text": "Will do."
    },
    {
      "turn_number": 82,
      "time": "2156-12-07 13:19:00",
      "speaker": "Doctor",
      "text": "Alright, you’re all set."
    },
    {
      "turn_number": 83,
      "time": "2156-12-07 13:20:00",
      "speaker": "Patient",
      "text": "Thanks again."
    },
    {
      "turn_number": 84,
      "time": "2156-12-07 13:21:00",
      "speaker": "Doctor",
      "text": "Take care. See you soon."
    },
    {
      "turn_number": 85,
      "time": "2156-12-07 13:22:00",
      "speaker": "Patient",
      "text": "Bye."
    }
  ],
  "summary": {
    "admission_start": "2156-11-25 20:18:00",
    "admission_end": "2156-12-07 14:22:00",
    "summary_paragraph": "The patient was admitted for evaluation of right-sided chest pain with palpitations and worsening chronic abdominal pain, nausea, and vomiting. She had uncontrolled type 1 diabetes due to loss of her glucometer and missed insulin doses. Initial workup ruled out myocardial infarction with normal EKGs and troponins. She accidentally dislodged her GJ tube during the admission, requiring temporary Foley placement and subsequent replacement by interventional radiology. A low-grade fever and erythema at the tube site led to a short course of clindamycin, with improvement. Pain was managed with IV Dilaudid and a structured regimen allowing one patient-chosen extra dose daily. Insulin was adjusted with endocrinology input, resulting in a new regimen of 60 units Lantus at bedtime and a sliding scale for Humalog. She improved clinically, maintained oral intake, and was discharged home in stable condition with instructions to complete antibiotics, follow up with her providers, and manage her diabetes and pain medications appropriately.",
    "problems": [
      "Chronic pancreatitis",
      "Attention to gastrostomy",
      "Hyposmolality and/or hyponatremia",
      "Diabetes with neurological manifestations, type I [juvenile type], uncontrolled",
      "Gastroparesis",
      "Malnutrition of mild degree",
      "Iron deficiency anemia, unspecified",
      "Opioid abuse, unspecified",
      "Gross hematuria",
      "Other chronic pain",
      "Unspecified personality disorder"
    ]
  }
}
